window.LESSON={"slug":"urban","title":"Tim Urban · Inside the mind of a master procrastinator · TED 2016","zhTitle":"拖延症患者的内心世界","audio":"../media/urban-ted.mp3","duration":834,"segments":[{"n":1,"zh":"大学论文：理想的计划","en":"The plan","from":0,"to":15,"s":4.08,"e":72.88,"vocab":[{"w":"government major","ipa":"/ˈɡʌvərnmənt ˈmeɪdʒər/","m":"n. 政治学专业","ex":"She was a government major in college.","exzh":"她大学读的是政治学专业。"},{"w":"spread out","ipa":"/spred aʊt/","m":"phr. 分散开；摊开","ex":"Spread the work out over the week.","exzh":"把工作分散到一周里。"},{"w":"civil","ipa":"/ˈsɪvl/","m":"adj. 文明的；平和有序的","ex":"Let's keep the discussion civil.","exzh":"我们讨论时保持礼貌、平和吧。"},{"w":"staircase","ipa":"/ˈsterkeɪs/","m":"n. 楼梯","ex":"He ran up the staircase.","exzh":"他跑上了楼梯。"},{"w":"kick it up into high gear","ipa":"/kɪk ɪt ʌp/","m":"phr. 加速；全力以赴","ex":"We kicked it up into high gear before the deadline.","exzh":"截止日期前我们全力冲刺。"}],"gist":{"q":"他原本打算怎么写论文？","opts":["一点点分散开，像上台阶一样逐步加量","最后一天一口气写完","请同学帮忙写"],"ans":0,"sum":"他说正常学生会把工作分散开；他给毕业论文也做了“台阶式”的计划，但实际并非如此。"}},{"n":2,"zh":"毕业论文惨案","en":"The thesis","from":16,"to":35,"s":74.57,"e":165.86,"vocab":[{"w":"thesis","ipa":"/ˈθiːsɪs/","m":"n. 毕业论文；论点","ex":"He spent a year on his thesis.","exzh":"他花了一年写毕业论文。"},{"w":"revised","ipa":"/rɪˈvaɪzd/","m":"adj. 修订过的","ex":"Here is the revised plan.","exzh":"这是修订后的计划。"},{"w":"deadline","ipa":"/ˈdedlaɪn/","m":"n. 截止日期","ex":"The deadline is Friday.","exzh":"截止日期是周五。"},{"w":"all-nighter","ipa":"/ˌɔːl ˈnaɪtər/","m":"n. 通宵（学习或工作）","ex":"I pulled an all-nighter before the exam.","exzh":"考试前我熬了个通宵。"},{"w":"sprint","ipa":"/sprɪnt/","m":"v. 冲刺；全速跑","ex":"She sprinted to catch the bus.","exzh":"她冲刺去赶公交车。"}],"gist":{"q":"毕业论文最后是怎么完成的？","opts":["提前一个月写完","最后三天、熬两个通宵写了九十页","学校同意延期"],"ans":1,"sum":"计划一再落空，最后三天他连熬两个通宵写完九十页；“最好的论文”只是个玩笑，其实写得很糟。"}},{"n":3,"zh":"拖延者的大脑","en":"Two brains","from":36,"to":51,"s":166.87,"e":241.41,"vocab":[{"w":"procrastination","ipa":"/proʊˌkræstɪˈneɪʃn/","m":"n. 拖延","ex":"Procrastination is the thief of time.","exzh":"拖延是时间的窃贼。"},{"w":"perplex","ipa":"/pərˈpleks/","m":"v. 使困惑","ex":"His answer perplexed everyone.","exzh":"他的回答让所有人都很困惑。"},{"w":"hypothesis","ipa":"/haɪˈpɑːθəsɪs/","m":"n. 假设","ex":"Scientists test the hypothesis with experiments.","exzh":"科学家用实验检验这个假设。"},{"w":"scan","ipa":"/skæn/","m":"v. 扫描","ex":"The doctor scanned my brain.","exzh":"医生给我做了脑部扫描。"},{"w":"instant gratification","ipa":"/ˈɪnstənt ˌɡrætɪfɪˈkeɪʃn/","m":"n. 即时满足","ex":"Social media offers instant gratification.","exzh":"社交媒体提供即时满足。"}],"gist":{"q":"他“扫描”出的两种大脑有什么不同？","opts":["拖延者的大脑更小","拖延者的大脑里多了一只“及时行乐猴”","两个大脑完全一样"],"ans":1,"sum":"两个大脑都有理性决策者，但拖延者的大脑里还住着一只及时行乐猴。"}},{"n":4,"zh":"猴子抢了方向盘","en":"The Monkey takes the wheel","from":52,"to":69,"s":243.66,"e":337.47,"vocab":[{"w":"productive","ipa":"/prəˈdʌktɪv/","m":"adj. 有成效的","ex":"I had a productive morning.","exzh":"我这个上午效率很高。"},{"w":"take the wheel","ipa":"/teɪk ðə wiːl/","m":"phr. 掌舵；接管控制","ex":"Let me take the wheel for a while.","exzh":"让我来开一会儿。"},{"w":"scandal","ipa":"/ˈskændl/","m":"n. 丑闻","ex":"The scandal was on every front page.","exzh":"这个丑闻上了所有报纸的头版。"},{"w":"spiral","ipa":"/ˈspaɪrəl/","m":"n. 螺旋；越陷越深的过程","ex":"I fell into a YouTube spiral last night.","exzh":"我昨晚刷视频停不下来。"},{"w":"tribal","ipa":"/ˈtraɪbl/","m":"adj. 部落的","ex":"Tribal life was simple but hard.","exzh":"部落生活简单却艰苦。"}],"gist":{"q":"猴子抢过方向盘后做了什么？","opts":["开始认真工作","读维基百科、翻冰箱、刷视频","去睡觉"],"ans":1,"sum":"猴子只在乎轻松和好玩，它把时间花在维基百科、冰箱和 YouTube 上；这在部落时代没问题，现代文明里就不行了。"}},{"n":5,"zh":"理性决策者与黑暗游乐场","en":"The Dark Playground","from":70,"to":89,"s":337.48,"e":428.25,"vocab":[{"w":"rational","ipa":"/ˈræʃənl/","m":"adj. 理性的","ex":"Try to make a rational decision.","exzh":"尽量做出理性的决定。"},{"w":"long-term","ipa":"/ˌlɔːŋ ˈtɜːrm/","m":"adj. 长期的","ex":"We need a long-term plan.","exzh":"我们需要一个长期计划。"},{"w":"overlap","ipa":"/ˈoʊvərlæp/","m":"n. 重叠","ex":"There is some overlap between the two jobs.","exzh":"这两份工作有一些重叠。"},{"w":"leisure","ipa":"/ˈliːʒər/","m":"n. 闲暇；休闲","ex":"What do you do in your leisure time?","exzh":"你闲暇时做什么？"},{"w":"guilt","ipa":"/ɡɪlt/","m":"n. 内疚","ex":"She felt a sense of guilt.","exzh":"她感到一阵内疚。"}],"gist":{"q":"“黑暗游乐场”是什么样的地方？","opts":["在不该休闲的时候休闲，充满内疚和焦虑","真正放松的度假地","工作效率最高的地方"],"ans":0,"sum":"理性决策者着眼大局，但拖延者常停留在“轻松好玩却不合理”的区域，那里的快乐伴随着内疚、焦虑和自我厌恶。"}},{"n":6,"zh":"恐慌怪兽","en":"The Panic Monster","from":90,"to":103,"s":428.62,"e":528.26,"vocab":[{"w":"guardian angel","ipa":"/ˈɡɑːrdiən ˈeɪndʒl/","m":"n. 守护天使","ex":"My grandma was my guardian angel.","exzh":"奶奶就是我的守护天使。"},{"w":"dormant","ipa":"/ˈdɔːrmənt/","m":"adj. 休眠的；暂停活动的","ex":"The volcano has been dormant for years.","exzh":"这座火山已经休眠多年。"},{"w":"embarrassment","ipa":"/ɪmˈbærəsmənt/","m":"n. 尴尬；难堪","ex":"His face turned red with embarrassment.","exzh":"他尴尬得脸都红了。"},{"w":"terrified","ipa":"/ˈterɪfaɪd/","m":"adj. 非常害怕的","ex":"She is terrified of spiders.","exzh":"她特别怕蜘蛛。"},{"w":"mayhem","ipa":"/ˈmeɪhem/","m":"n. 混乱；骚乱","ex":"The kids caused mayhem in the kitchen.","exzh":"孩子们把厨房搞得一团糟。"}],"gist":{"q":"什么能让猴子逃走？","opts":["理性决策者的说服","恐慌怪兽","朋友的提醒"],"ans":1,"sum":"截止日期临近或可能当众出丑时，恐慌怪兽醒来，猴子吓得上树，理性决策者才终于能掌舵——他准备这场 TED 演讲时也是如此。"}},{"n":7,"zh":"怪兽醒了：终于开工","en":"The Monster wakes up","from":104,"to":113,"s":532.29,"e":596.88,"vocab":[{"w":"release","ipa":"/rɪˈliːs/","m":"v. 公布；发布","ex":"The band released a new album.","exzh":"乐队发布了新专辑。"},{"w":"stare","ipa":"/ster/","m":"v. 盯着看","ex":"Don't stare at people.","exzh":"别盯着别人看。"},{"w":"lose one's mind","ipa":"/luːz wʌnz maɪnd/","m":"phr. 抓狂；发疯","ex":"I almost lost my mind waiting.","exzh":"等得我差点抓狂。"},{"w":"insane","ipa":"/ɪnˈseɪn/","m":"adj. 疯狂的；荒唐的","ex":"That's an insane idea.","exzh":"这个想法太疯狂了。"},{"w":"work ethic","ipa":"/wɜːrk ˈeθɪk/","m":"n. 职业精神；干劲","ex":"She has a strong work ethic.","exzh":"她工作非常勤奋。"}],"gist":{"q":"他看到 TED 官网上自己的照片后发生了什么？","opts":["猴子继续拖延","恐慌怪兽醒来，猴子逃上树，他终于开始准备","他取消了演讲"],"ans":1,"sum":"截止日期逼近，恐慌怪兽抓狂，猴子吓得上树，理性决策者掌舵；这也解释了拖延者为何能一夜写出八页。"}},{"n":8,"zh":"成千上万封来信","en":"The emails","from":114,"to":122,"s":597.17,"e":646.11,"vocab":[{"w":"contrast","ipa":"/ˈkɑːntræst/","m":"n. 对比；反差","ex":"There is a sharp contrast between the two cities.","exzh":"这两座城市反差很大。"},{"w":"frustration","ipa":"/frʌˈstreɪʃn/","m":"n. 挫败感；沮丧","ex":"He shouted in frustration.","exzh":"他沮丧地大喊。"},{"w":"literally","ipa":"/ˈlɪtərəli/","m":"adv. 真的；简直","ex":"I literally ran all the way.","exzh":"我真的是一路跑过去的。"},{"w":"struck","ipa":"/strʌk/","m":"v. (strike 过去式) 让人震动；打动","ex":"What struck me was her honesty.","exzh":"让我印象深刻的是她的诚实。"},{"w":"tone","ipa":"/toʊn/","m":"n. 语气；基调","ex":"The tone of the letter was friendly.","exzh":"信的语气很友好。"}],"gist":{"q":"读者来信让他意外的是什么？","opts":["邮件很少","文章很轻松，来信却很沉重","大家都说自己不拖延"],"ans":1,"sum":"成千上万封来信都说“我也有这个问题”，而且充满挫败感——如果这个系统管用，为什么大家这么痛苦？"}},{"n":9,"zh":"两种拖延","en":"Two kinds of procrastination","from":123,"to":140,"s":646.11,"e":747.8,"vocab":[{"w":"deadline-based","ipa":"/ˈdedlaɪn beɪst/","m":"adj. 以截止日期为准的","ex":"Most school work is deadline-based.","exzh":"大多数课业都以截止日期为准。"},{"w":"contain","ipa":"/kənˈteɪn/","m":"v. 控制；限制","ex":"They managed to contain the fire.","exzh":"他们控制住了火势。"},{"w":"entrepreneurial","ipa":"/ˌɑːntrəprəˈnɜːriəl/","m":"adj. 创业的","ex":"She has an entrepreneurial spirit.","exzh":"她有创业精神。"},{"w":"mechanism","ipa":"/ˈmekənɪzəm/","m":"n. 机制","ex":"the body's defense mechanism","exzh":"身体的防御机制"},{"w":"regret","ipa":"/rɪˈɡret/","m":"n./v. 遗憾；后悔","ex":"I have no regrets.","exzh":"我没有遗憾。"}],"gist":{"q":"他认为哪一种拖延更可怕？","opts":["有截止日期的短期拖延","没有截止日期的长期拖延","两种一样"],"ans":1,"sum":"读者来信让他发现：没有截止日期时恐慌怪兽不会出现，拖延的影响会无限扩散，带来长期的不快乐和遗憾。"}},{"n":10,"zh":"人生日历","en":"The Life Calendar","from":141,"to":157,"s":748.19,"e":825.65,"vocab":[{"w":"spectator","ipa":"/ˈspekteɪtər/","m":"n. 旁观者；观众","ex":"Don't be a spectator in your own life.","exzh":"别做自己人生的旁观者。"},{"w":"epiphany","ipa":"/ɪˈpɪfəni/","m":"n. 顿悟","ex":"I had an epiphany in the shower.","exzh":"我洗澡时突然顿悟了。"},{"w":"sneaky","ipa":"/ˈsniːki/","m":"adj. 狡猾的；鬼鬼祟祟的","ex":"That was a sneaky trick.","exzh":"那是个狡猾的把戏。"},{"w":"take a hard look at","ipa":"/teɪk ə hɑːrd lʊk/","m":"phr. 认真审视","ex":"We need to take a hard look at our spending.","exzh":"我们需要认真审视一下开支。"},{"w":"stay aware of","ipa":"/steɪ əˈwer/","m":"phr. 时刻留意","ex":"Stay aware of your surroundings.","exzh":"时刻留意周围的环境。"}],"gist":{"q":"“人生日历”想提醒我们什么？","opts":["我们的周数并没有那么多，要尽早开始","日历要买大一点的","每周都要休息"],"ans":0,"sum":"他认为人人都在拖延某件事；人生按周算格子并不多，所以要警惕那只猴子，最好从今天——或者很快——开始。"}}],"sentences":[{"id":0,"p":0,"en":"So in college, I was a government major, which means I had to write a lot of papers.","zh":"上大学时，我读的是政治学专业，这意味着我得写很多论文。","s":4.08,"e":10.58,"w":[[4.2,4.26],[4.34,4.4],[4.48,5.08],[7.04,7.08],[7.1,7.18],[7.22,7.24],[7.3,7.69],[7.71,8.07],[8.49,8.63],[8.67,8.87],[8.95,8.97],[8.99,9.13],[9.15,9.21],[9.25,9.45],[9.47,9.49],[9.53,9.67],[9.71,9.75],[9.83,10.33]]},{"id":1,"p":0,"en":"Now, when a normal student writes a paper, they might spread the work out a little like this.","zh":"一个正常的学生写论文，可能会像这样把工作量分散开。","s":10.87,"e":14.28,"w":[[10.99,11.17],[11.25,11.33],[11.35,11.37],[11.43,11.67],[11.71,11.97],[11.97,12.15],[12.17,12.21],[12.21,12.45],[12.47,12.55],[12.55,12.71],[12.73,12.95],[12.95,13.01],[13.07,13.25],[13.29,13.39],[13.41,13.43],[13.45,13.59],[13.61,13.79],[13.81,14.03]]},{"id":2,"p":0,"en":"So, you know --","zh":"所以，你知道——","s":15.27,"e":16.0,"w":[[15.39,15.45],[15.53,15.59],[15.59,15.75]]},{"id":3,"p":2,"en":"you get started maybe a little slowly, but you get enough done in the first week that, with some heavier days later on, everything gets done, things stay civil.","zh":"一开始也许慢一点，但第一周就完成了足够多的部分，后面再有几天多干一点，一切都能按时完成，事情井井有条。","s":18.23,"e":25.79,"w":[[18.35,18.45],[18.71,18.83],[18.87,19.15],[19.17,19.29],[19.33,19.35],[19.37,19.53],[19.57,19.89],[19.91,19.99],[20.01,20.07],[20.09,20.17],[20.21,20.43],[20.51,20.69],[20.69,20.75],[20.77,20.83],[20.87,21.13],[21.19,21.39],[21.49,21.65],[21.95,22.07],[22.09,22.21],[22.23,22.51],[22.53,22.74],[22.78,22.98],[23.08,23.24],[23.94,24.2],[24.22,24.36],[24.42,24.62],[24.76,24.94],[24.98,25.14],[25.28,25.54]]},{"id":4,"p":4,"en":"And I would want to do that like that.","zh":"我也想那样做，就像那样。","s":27.42,"e":29.57,"w":[[27.54,27.62],[27.72,27.74],[27.76,27.88],[27.92,28.06],[28.1,28.14],[28.24,28.34],[28.5,28.76],[28.86,29.06],[29.08,29.32]]},{"id":5,"p":4,"en":"That would be the plan.","zh":"那本来是我的计划。","s":29.62,"e":30.73,"w":[[29.74,29.88],[29.88,29.98],[30.0,30.06],[30.08,30.14],[30.18,30.48]]},{"id":6,"p":4,"en":"I would have it all ready to go, but then, actually, the paper would come along, and then I would kind of do this.","zh":"我一切都准备就绪，可是真到写论文的时候，我却会变成这样。","s":32.18,"e":37.31,"w":[[32.3,32.32],[32.34,32.46],[32.48,32.64],[32.66,32.72],[32.76,32.84],[32.88,33.04],[33.08,33.12],[33.18,33.28],[33.48,33.58],[33.62,33.74],[34.42,34.68],[34.7,34.78],[34.8,35.08],[35.36,35.48],[35.48,35.62],[35.64,35.98],[36.02,36.08],[36.08,36.18],[36.24,36.26],[36.26,36.36],[36.36,36.52],[36.52,36.56],[36.62,36.68],[36.76,37.06]]},{"id":7,"p":6,"en":"And that would happen every single paper.","zh":"而且每一篇论文都是这样。","s":40.27,"e":42.3,"w":[[40.39,40.47],[40.49,40.59],[40.63,40.73],[40.77,41.05],[41.19,41.39],[41.45,41.71],[41.73,42.05]]},{"id":8,"p":7,"en":"But then came my 90-page senior thesis, a paper you're supposed to spend a year on.","zh":"后来轮到我那篇九十页的毕业论文了，这种论文本该花一整年来写。","s":43.07,"e":48.98,"w":[[43.19,43.31],[43.37,43.55],[43.71,44.09],[44.17,44.33],[44.49,44.89],[45.01,45.51],[45.73,46.05],[46.15,46.61],[47.13,47.15],[47.19,47.39],[47.39,47.51],[47.51,47.73],[47.73,47.79],[47.81,48.03],[48.07,48.09],[48.21,48.41],[48.51,48.73]]},{"id":9,"p":7,"en":"And I knew for a paper like that, my normal work flow was not an option.","zh":"我知道，对这样一篇论文，我平常的那套做法是行不通的。","s":49.33,"e":52.96,"w":[[49.45,49.51],[49.55,49.57],[49.57,49.67],[49.71,49.79],[49.81,49.83],[49.87,50.11],[50.15,50.31],[50.33,50.61],[50.79,50.89],[50.93,51.21],[51.37,51.59],[51.67,51.93],[52.23,52.35],[52.39,52.51],[52.55,52.63],[52.69,53.03]]},{"id":10,"p":7,"en":"It was way too big a project.","zh":"这个项目实在太大了。","s":52.96,"e":54.4,"w":[[53.08,53.14],[53.14,53.22],[53.26,53.36],[53.42,53.52],[53.54,53.64],[53.66,53.68],[53.72,54.18]]},{"id":11,"p":7,"en":"So I planned things out, and I decided I kind of had to go something like this.","zh":"所以我做了计划，决定大概要按这样的节奏来。","s":54.4,"e":58.77,"w":[[54.52,54.56],[54.64,54.66],[54.7,54.94],[54.96,55.14],[55.24,55.4],[55.4,55.48],[55.52,55.54],[55.56,55.94],[56.54,56.56],[56.62,56.84],[56.86,56.9],[57.28,57.46],[57.5,57.56],[57.62,57.7],[57.86,58.08],[58.1,58.24],[58.28,58.52]]},{"id":12,"p":7,"en":"This is how the year would go.","zh":"这一年就打算这么过。","s":59.32,"e":60.41,"w":[[59.44,59.52],[59.52,59.56],[59.58,59.68],[59.68,59.74],[59.8,59.92],[59.92,60.12],[60.12,60.16]]},{"id":13,"p":7,"en":"So I'd start off light, and I'd bump it up in the middle months, and then at the end, I would kick it up into high gear just like a little staircase.","zh":"先轻松起步，中间几个月加大力度，到最后再全速冲刺，就像一个小台阶。","s":60.48,"e":69.11,"w":[[60.6,60.66],[60.78,60.84],[60.9,61.18],[61.26,61.46],[61.62,61.88],[62.9,63.0],[63.06,63.12],[63.26,63.44],[63.46,63.52],[63.56,63.64],[63.7,63.76],[63.78,63.86],[63.88,64.06],[64.1,64.38],[65.22,65.32],[65.34,65.6],[65.76,65.82],[65.84,65.9],[66.0,66.28],[66.6,66.62],[66.62,66.74],[66.78,66.94],[66.96,67.02],[67.02,67.1],[67.12,67.24],[67.28,67.5],[67.52,67.74],[67.84,67.96],[67.96,68.1],[68.1,68.12],[68.14,68.33],[68.37,69.07]]},{"id":14,"p":7,"en":"How hard could it be to walk up the stairs?","zh":"爬个楼梯能有多难？","s":69.11,"e":71.28,"w":[[69.23,69.33],[69.39,69.53],[69.55,69.65],[69.65,69.69],[69.69,69.73],[69.79,69.87],[69.99,70.23],[70.27,70.33],[70.39,70.45],[70.53,71.03]]},{"id":15,"p":7,"en":"No big deal, right?","zh":"没什么大不了的，对吧？","s":71.73,"e":72.88,"w":[[71.85,71.91],[71.97,72.09],[72.15,72.31],[72.39,72.63]]},{"id":16,"p":8,"en":"But then, the funniest thing happened.","zh":"可是接下来，最搞笑的事情发生了。","s":74.57,"e":76.33,"w":[[74.69,74.81],[74.93,75.25],[75.37,75.43],[75.45,75.79],[75.81,75.95],[75.99,76.33]]},{"id":17,"p":8,"en":"Those first few months?","zh":"最开始那几个月？","s":76.33,"e":77.68,"w":[[76.45,76.67],[76.71,76.93],[76.97,77.09],[77.13,77.43]]},{"id":18,"p":8,"en":"They came and went, and I couldn't quite do stuff.","zh":"转眼就过去了，我什么也没干成。","s":78.25,"e":80.78,"w":[[78.37,78.47],[78.51,78.67],[78.69,78.77],[78.81,78.99],[79.03,79.11],[79.43,79.45],[79.47,79.69],[79.69,79.95],[80.03,80.11],[80.23,80.53]]},{"id":19,"p":8,"en":"So we had an awesome new revised plan.","zh":"于是我们有了一个很棒的新修订计划。","s":81.03,"e":83.08,"w":[[81.15,81.21],[81.23,81.29],[81.31,81.39],[81.39,81.43],[81.59,81.89],[81.91,82.03],[82.07,82.51],[82.57,82.83]]},{"id":20,"p":10,"en":"And then --","zh":"然后——","s":84.16,"e":84.64,"w":[[84.28,84.38],[84.38,84.64]]},{"id":21,"p":12,"en":"But then those middle months actually went by, and I didn't really write words, and so we were here.","zh":"可是中间那几个月真的也过去了，我几乎一个字都没写，于是我们就到了这里。","s":84.64,"e":94.07,"w":[[87.28,87.38],[87.4,87.54],[87.58,87.78],[87.9,88.16],[88.2,88.44],[88.5,88.74],[88.78,88.9],[88.96,89.28],[90.18,90.26],[90.4,90.42],[90.48,90.68],[90.7,90.88],[90.9,91.16],[91.24,91.76],[92.44,93.04],[93.18,93.26],[93.36,93.42],[93.42,93.54],[93.58,93.82]]},{"id":22,"p":12,"en":"And then two months turned into one month, which turned into two weeks.","zh":"接着两个月变成了一个月，一个月又变成了两周。","s":95.0,"e":99.1,"w":[[95.12,95.2],[95.2,95.32],[95.4,95.56],[95.6,95.86],[96.2,96.4],[96.42,96.58],[96.7,96.84],[96.88,97.14],[97.14,97.72],[97.72,97.92],[97.96,98.18],[98.26,98.44],[98.51,98.85]]},{"id":23,"p":12,"en":"And one day I woke up with three days until the deadline, still not having written a word, and so I did the only thing I could: I wrote 90 pages over 72 hours,","zh":"有一天我醒来，离截止日期只剩三天，我还一个字都没写，于是我只能做唯一能做的事：七十二小时写了九十页，","s":99.27,"e":111.65,"w":[[99.39,99.47],[99.51,99.61],[99.63,99.75],[99.81,99.83],[99.87,100.11],[100.15,100.29],[101.35,101.49],[101.59,101.85],[101.93,102.41],[102.53,102.75],[102.79,102.85],[102.91,103.53],[105.03,105.27],[105.33,105.49],[105.55,105.81],[105.83,106.07],[106.13,106.15],[106.23,106.61],[107.07,107.17],[107.19,107.25],[107.37,107.39],[107.43,107.55],[107.57,107.63],[107.69,107.83],[107.89,108.03],[108.13,108.15],[108.23,108.47],[109.25,109.27],[109.31,109.57],[109.67,110.01],[110.11,110.49],[110.53,110.69],[110.77,111.07],[111.15,111.29],[111.33,111.69]]},{"id":24,"p":12,"en":"pulling not one but two all-nighters -- humans are not supposed to pull two all-nighters -- sprinted across campus, dove in slow motion, and got it in just at the deadline.","zh":"不是熬了一个通宵，而是两个——人类本来就不该连熬两个通宵——然后冲过校园，慢动作扑过去，刚好在截止时间交了上去。","s":111.65,"e":123.33,"w":[[111.77,112.03],[112.07,112.23],[112.33,112.45],[112.47,112.57],[112.67,112.91],[113.05,113.15],[113.19,113.61],[114.02,114.34],[114.38,114.46],[114.48,114.64],[114.68,115.04],[115.08,115.12],[115.18,115.34],[115.4,115.52],[115.58,115.66],[115.72,116.14],[118.08,118.56],[118.58,118.86],[118.94,119.36],[120.02,120.14],[120.16,120.2],[120.28,120.5],[120.6,121.02],[121.5,121.6],[121.64,121.82],[121.84,121.92],[121.96,122.06],[122.16,122.36],[122.42,122.46],[122.48,122.54],[122.6,123.08]]},{"id":25,"p":13,"en":"I thought that was the end of everything.","zh":"我以为一切就这样结束了。","s":123.54,"e":125.07,"w":[[123.66,123.68],[123.7,123.84],[123.86,123.94],[123.98,124.06],[124.08,124.16],[124.22,124.32],[124.36,124.42],[124.44,124.82]]},{"id":26,"p":13,"en":"But a week later I get a call, and it's the school.","zh":"可是一周后我接到一个电话，是学校打来的。","s":125.1,"e":128.19,"w":[[125.22,125.32],[125.34,125.36],[125.4,125.54],[125.6,125.78],[125.86,125.88],[125.9,126.0],[126.02,126.04],[126.1,126.46],[127.22,127.3],[127.3,127.4],[127.4,127.46],[127.58,127.94]]},{"id":27,"p":13,"en":"And they say, \"Is this Tim Urban?\"","zh":"他们说：“是蒂姆·厄本吗？”","s":129.23,"e":130.75,"w":[[129.35,129.43],[129.45,129.53],[129.59,129.81],[130.01,130.07],[130.09,130.21],[130.35,130.51],[130.59,130.83]]},{"id":28,"p":13,"en":"And I say, \"Yeah.\"","zh":"我说：“是我。”","s":130.75,"e":132.06,"w":[[130.87,130.95],[131.03,131.05],[131.09,131.27],[131.63,131.81]]},{"id":29,"p":13,"en":"And they say, \"We need to talk about your thesis.\"","zh":"他们说：“我们需要谈谈你的毕业论文。”","s":132.35,"e":134.4,"w":[[132.47,132.55],[132.55,132.65],[132.69,132.79],[132.85,132.91],[132.97,133.09],[133.11,133.15],[133.17,133.35],[133.39,133.53],[133.55,133.65],[133.71,134.15]]},{"id":30,"p":13,"en":"And I say, \"OK.\"","zh":"我说：“好的。”","s":134.51,"e":135.54,"w":[[134.63,134.71],[134.77,134.81],[134.85,135.01],[135.19,135.29]]},{"id":31,"p":13,"en":"And they say, \"It's the best one we've ever seen.\"","zh":"他们说：“这是我们见过最好的一篇。”","s":136.97,"e":140.3,"w":[[137.09,137.17],[137.17,137.27],[137.35,137.59],[138.73,138.87],[138.87,138.95],[138.99,139.19],[139.27,139.37],[139.39,139.53],[139.55,139.69],[139.79,140.05]]},{"id":32,"p":16,"en":"That did not happen.","zh":"这事并没有发生。","s":148.46,"e":149.83,"w":[[148.58,148.74],[148.82,148.96],[149.02,149.18],[149.24,149.58]]},{"id":33,"p":18,"en":"It was a very, very bad thesis.","zh":"那是一篇非常、非常糟糕的论文。","s":151.74,"e":154.93,"w":[[151.86,151.92],[151.96,152.06],[152.12,152.14],[152.28,152.62],[153.5,153.78],[153.88,154.16],[154.24,154.68]]},{"id":34,"p":20,"en":"I just wanted to enjoy that one moment when all of you thought, \"This guy is amazing!\"","zh":"我只是想享受一下你们所有人都在想“这家伙太厉害了！”的那一刻。","s":156.86,"e":162.87,"w":[[156.98,157.0],[157.12,157.48],[158.14,158.72],[158.84,158.94],[159.0,159.31],[159.35,159.51],[159.67,159.79],[159.81,160.07],[160.09,160.19],[160.43,160.67],[160.73,160.81],[160.87,160.97],[161.03,161.25],[161.27,161.43],[161.53,161.75],[161.83,161.91],[161.97,162.75]]},{"id":35,"p":22,"en":"No, no, it was very, very bad.","zh":"不，不，它真的非常非常糟糕。","s":162.87,"e":165.86,"w":[[164.37,164.45],[164.55,164.63],[164.73,164.79],[164.79,164.89],[164.91,165.11],[165.17,165.33],[165.39,165.61]]},{"id":36,"p":22,"en":"Anyway, today I'm a writer-blogger guy.","zh":"总之，如今我是个写作的博主。","s":166.87,"e":170.28,"w":[[166.99,167.43],[167.81,168.17],[168.37,168.45],[168.49,168.51],[168.59,168.95],[169.13,169.59],[169.71,170.03]]},{"id":37,"p":22,"en":"I write the blog Wait But Why.","zh":"我写的博客叫 Wait But Why（等等，为什么）。","s":170.31,"e":171.9,"w":[[170.43,170.45],[170.45,170.63],[170.65,170.71],[170.71,170.95],[171.01,171.19],[171.29,171.41],[171.43,171.65]]},{"id":38,"p":22,"en":"And a couple of years ago, I decided to write about procrastination.","zh":"几年前，我决定写写拖延症。","s":172.07,"e":175.75,"w":[[172.19,172.49],[172.89,172.91],[172.95,173.13],[173.13,173.17],[173.19,173.37],[173.39,173.53],[173.67,173.69],[173.71,174.03],[174.07,174.13],[174.17,174.4],[174.42,174.62],[174.66,175.5]]},{"id":39,"p":22,"en":"My behavior has always perplexed the non-procrastinators around me, and","zh":"我的行为一直让身边不拖延的人感到困惑，","s":175.78,"e":179.26,"w":[[175.9,175.98],[176.02,176.32],[176.32,176.38],[176.4,176.56],[176.62,177.28],[177.4,177.46],[177.52,177.7],[177.76,178.52],[178.56,178.8],[178.82,178.88],[179.26,179.32]]},{"id":40,"p":22,"en":"I wanted to explain to the non-procrastinators of the world what goes on in the heads of procrastinators, and why we are the way we are.","zh":"我想向世界上不拖延的人解释，拖延者的脑子里在想什么，以及我们为什么会这样。","s":179.26,"e":185.76,"w":[[179.38,179.4],[179.42,179.6],[179.64,179.68],[179.74,180.14],[180.18,180.24],[180.26,180.32],[180.38,180.58],[180.62,181.32],[181.34,181.4],[181.42,181.5],[181.58,181.96],[182.94,183.06],[183.1,183.24],[183.3,183.38],[183.42,183.46],[183.48,183.56],[183.6,183.82],[183.84,183.88],[183.9,184.52],[184.54,184.6],[184.62,184.78],[184.82,184.88],[184.96,185.06],[185.06,185.12],[185.14,185.24],[185.26,185.32],[185.42,185.58]]},{"id":41,"p":22,"en":"Now, I had a hypothesis that the brains of procrastinators were actually different than the brains of other people.","zh":"我有一个假设：拖延者的大脑其实和其他人的大脑不一样。","s":185.76,"e":192.5,"w":[[185.88,185.96],[186.02,186.04],[186.04,186.12],[186.12,186.14],[186.18,187.04],[187.52,187.64],[187.98,188.04],[188.14,188.5],[188.52,188.56],[188.58,189.24],[189.26,189.38],[189.47,189.79],[190.03,190.45],[190.55,190.67],[190.69,190.77],[190.85,191.35],[191.55,191.63],[191.71,191.87],[191.93,192.25]]},{"id":42,"p":22,"en":"And to test this, I found an MRI lab that actually let me scan both my brain and the brain of a proven non-procrastinator, so I could compare them.","zh":"为了验证这一点，我找到一家核磁共振实验室，让我扫描了自己的大脑和一位公认不拖延的人的大脑，好做个比较。","s":193.25,"e":202.06,"w":[[193.37,193.69],[193.81,193.87],[193.93,194.19],[194.23,194.43],[194.59,194.61],[194.65,194.81],[194.83,194.91],[195.05,195.37],[195.43,195.59],[195.61,195.69],[195.73,195.99],[196.03,196.13],[196.17,196.21],[196.37,196.67],[196.75,196.95],[197.01,197.19],[197.29,197.57],[198.05,198.21],[198.25,198.31],[198.35,198.53],[198.55,198.61],[198.65,198.67],[198.73,199.05],[199.09,199.27],[199.31,200.09],[201.03,201.15],[201.15,201.17],[201.17,201.29],[201.31,201.65],[201.67,201.81]]},{"id":43,"p":22,"en":"I actually brought them here to show you today.","zh":"今天我特地把它们带来给大家看。","s":202.21,"e":204.19,"w":[[202.33,202.35],[202.35,202.57],[202.61,202.85],[202.89,202.99],[203.07,203.27],[203.29,203.33],[203.43,203.57],[203.63,203.71],[203.77,204.09]]},{"id":44,"p":22,"en":"I want you to take a look carefully to see if you can notice a difference.","zh":"请大家仔细看看，能不能发现区别。","s":204.19,"e":206.86,"w":[[204.31,204.33],[204.33,204.45],[204.47,204.53],[204.53,204.6],[204.64,204.8],[204.82,204.84],[204.9,205.04],[205.1,205.5],[205.52,205.58],[205.66,205.8],[205.84,205.88],[205.94,206.02],[206.02,206.12],[206.18,206.42],[206.44,206.46],[206.5,206.82]]},{"id":45,"p":22,"en":"I know that if you're not a trained brain expert, it's not that obvious, but just take a look, OK?","zh":"我知道如果你不是受过训练的大脑专家，区别并不明显，但还是看一看，好吗？","s":206.86,"e":211.19,"w":[[206.98,207.0],[207.04,207.26],[207.32,207.4],[207.44,207.48],[207.5,207.64],[207.64,207.7],[207.72,207.74],[207.8,208.16],[208.22,208.42],[208.48,208.82],[208.88,208.96],[209.0,209.16],[209.24,209.46],[209.78,210.14],[210.18,210.28],[210.3,210.42],[210.44,210.62],[210.64,210.66],[210.72,210.94],[211.08,211.16]]},{"id":46,"p":22,"en":"So here's the brain of a non-procrastinator.","zh":"这是不拖延者的大脑。","s":211.19,"e":214.31,"w":[[212.0,212.06],[212.18,212.4],[212.44,212.5],[212.54,212.78],[212.82,212.88],[212.92,212.94],[213.02,213.24],[213.32,214.06]]},{"id":47,"p":24,"en":"Now ... here's my brain.","zh":"现在……这是我的大脑。","s":216.74,"e":221.2,"w":[[217.8,218.02],[219.95,220.23],[220.41,220.59],[220.67,220.95]]},{"id":48,"p":26,"en":"There is a difference.","zh":"确实有区别。","s":227.21,"e":228.72,"w":[[227.33,227.49],[227.79,227.89],[227.93,227.95],[228.03,228.47]]},{"id":49,"p":26,"en":"Both brains have a Rational Decision-Maker in them, but the procrastinator's brain also has an Instant Gratification Monkey.","zh":"两个大脑里都有一个“理性决策者”，但拖延者的大脑里还多了一只“及时行乐猴”。","s":229.45,"e":236.52,"w":[[229.57,229.83],[229.91,230.21],[230.25,230.35],[230.37,230.39],[230.47,230.89],[230.93,231.33],[231.37,231.61],[231.67,231.73],[231.77,231.89],[231.95,232.07],[232.09,232.15],[232.21,232.99],[233.05,233.27],[233.75,234.05],[234.13,234.27],[234.31,234.37],[234.55,234.96],[235.04,235.82],[235.96,236.34]]},{"id":50,"p":26,"en":"Now, what does this mean for the procrastinator?","zh":"那么，这对拖延者意味着什么呢？","s":236.52,"e":238.08,"w":[[236.64,236.76],[236.84,236.94],[236.96,237.06],[237.08,237.2],[237.24,237.38],[237.4,237.48],[237.48,237.54],[237.56,238.16]]},{"id":51,"p":26,"en":"Well, it means everything's fine until this happens.","zh":"意思是，一切都好好的，直到发生这种事。","s":238.08,"e":241.41,"w":[[238.2,238.38],[238.76,238.84],[238.94,239.1],[239.14,239.48],[239.54,239.92],[240.22,240.46],[240.5,240.64],[240.7,241.16]]},{"id":52,"p":28,"en":"So the Rational Decision-Maker will make the rational decision to do something productive, but the Monkey doesn't like that plan, so he actually takes the wheel, and","zh":"理性决策者会做出理性的决定，去干点有用的事，但猴子不喜欢这个计划，于是它直接抢过方向盘，","s":243.66,"e":252.39,"w":[[243.78,243.84],[243.88,243.94],[244.0,244.38],[244.42,244.78],[244.82,245.12],[245.2,245.3],[245.34,245.58],[245.64,245.72],[245.8,246.22],[246.24,246.66],[247.02,247.1],[247.5,247.58],[247.74,248.06],[248.1,248.74],[248.98,249.06],[249.08,249.14],[249.16,249.38],[249.44,249.68],[249.74,249.96],[249.98,250.17],[250.23,250.55],[250.93,250.99],[251.07,251.13],[251.15,251.37],[251.37,251.61],[251.65,251.71],[251.77,252.01],[252.41,252.49]]},{"id":53,"p":28,"en":"he says, \"Actually, let's read the entire Wikipedia page of the Nancy Kerrigan/ Tonya Harding scandal, because I just remembered that that happened.","zh":"它说：“其实，我们去把维基百科上南希·克里根和托尼娅·哈丁丑闻的整个页面读一遍吧，因为我刚想起来有这么回事。","s":252.39,"e":259.18,"w":[[252.51,252.57],[252.67,252.91],[253.35,253.71],[253.75,253.95],[254.03,254.19],[254.21,254.27],[254.31,254.65],[254.67,255.19],[255.23,255.43],[255.45,255.49],[255.51,255.57],[255.65,255.93],[256.01,256.35],[256.39,256.69],[256.75,257.03],[257.09,257.37],[257.37,257.51],[257.57,257.59],[257.67,257.89],[257.95,258.29],[258.29,258.37],[258.39,258.53],[258.57,258.93]]},{"id":54,"p":30,"en":"Then --","zh":"然后——","s":260.11,"e":260.47,"w":[[260.23,260.47]]},{"id":55,"p":32,"en":"Then we're going to go over to the fridge, to see if there's anything new in there since 10 minutes ago.","zh":"然后我们去冰箱那儿看看，十分钟前到现在有没有什么新东西。","s":260.47,"e":266.61,"w":[[263.19,263.29],[263.31,263.41],[263.41,263.53],[263.53,263.57],[263.57,263.63],[263.69,263.79],[263.81,263.85],[263.89,263.95],[264.03,264.37],[264.37,264.41],[264.47,264.59],[264.61,264.65],[264.65,264.79],[264.79,265.05],[265.09,265.22],[265.24,265.28],[265.3,265.44],[265.46,265.64],[265.68,265.86],[265.94,266.18],[266.22,266.36]]},{"id":56,"p":32,"en":"After that, we're going to go on a YouTube spiral that starts with videos of Richard Feynman talking about magnets and ends much,","zh":"之后，我们来一场 YouTube 连环看：从理查德·费曼讲磁铁的视频开始，一直看到很久、","s":267.42,"e":274.86,"w":[[267.54,267.8],[267.84,268.1],[269.18,269.28],[269.28,269.4],[269.4,269.44],[269.44,269.5],[269.54,269.6],[269.64,269.66],[269.76,270.18],[270.26,270.82],[270.84,270.94],[271.04,271.4],[271.62,271.74],[271.76,272.04],[272.06,272.12],[272.18,272.46],[272.5,272.84],[272.9,273.24],[273.26,273.56],[273.7,274.22],[274.26,274.34],[274.42,274.6],[274.72,274.92]]},{"id":57,"p":32,"en":"much later with us watching interviews with Justin Bieber's mom.","zh":"很久以后，我们在看贾斯汀·比伯妈妈的访谈。","s":274.86,"e":278.43,"w":[[274.98,275.16],[275.22,275.48],[275.7,275.8],[275.82,275.9],[275.96,276.26],[276.36,276.82],[276.84,276.94],[276.98,277.34],[277.4,277.76],[277.84,278.18]]},{"id":58,"p":34,"en":"\"All of that's going to take a while, so we're not going to really have room on the schedule for any work today.","zh":"“这些都得花点时间，所以今天的日程里真的没空干活了。","s":280.87,"e":285.39,"w":[[280.99,281.13],[281.17,281.23],[281.25,281.45],[281.49,281.61],[281.61,281.65],[281.73,281.99],[282.03,282.05],[282.15,282.61],[282.75,282.83],[282.93,283.05],[283.07,283.19],[283.23,283.37],[283.37,283.41],[283.43,283.59],[283.61,283.73],[283.79,283.93],[283.95,284.03],[284.03,284.11],[284.19,284.57],[284.61,284.71],[284.73,284.83],[284.91,285.07],[285.13,285.37]]},{"id":59,"p":34,"en":"Sorry!\"","zh":"抱歉！”","s":285.39,"e":286.12,"w":[[285.51,285.87]]},{"id":60,"p":36,"en":"Now, what is going on here?","zh":"那么，这到底是怎么回事？","s":289.85,"e":293.12,"w":[[289.97,290.21],[290.63,290.95],[291.35,291.43],[291.53,291.85],[291.93,292.33],[292.57,292.87]]},{"id":61,"p":36,"en":"The Instant Gratification Monkey does not seem like a guy you want behind the wheel.","zh":"及时行乐猴看起来可不像是你愿意让它开车的家伙。","s":295.01,"e":298.8,"w":[[295.13,295.19],[295.23,295.49],[295.54,296.24],[296.3,296.56],[296.62,296.76],[296.86,297.08],[297.2,297.38],[297.42,297.58],[297.58,297.6],[297.68,297.88],[297.92,298.0],[298.02,298.22],[298.24,298.48],[298.5,298.56],[298.62,298.84]]},{"id":62,"p":36,"en":"He lives entirely in the present moment.","zh":"它完全活在当下。","s":298.8,"e":300.86,"w":[[298.92,298.96],[299.04,299.2],[299.24,299.8],[299.84,299.88],[299.9,299.96],[300.02,300.3],[300.34,300.66]]},{"id":63,"p":36,"en":"He has no memory of the past, no knowledge of the future, and he only cares about two things: easy and fun.","zh":"它不记得过去，也不了解未来，它只在乎两件事：轻松和好玩。","s":300.86,"e":307.27,"w":[[300.98,301.04],[301.06,301.18],[301.38,301.5],[301.62,301.94],[302.02,302.08],[302.1,302.18],[302.22,302.64],[303.04,303.12],[303.2,303.52],[303.52,303.58],[303.58,303.64],[303.68,303.96],[303.98,304.04],[304.04,304.08],[304.12,304.24],[304.28,304.46],[304.48,304.64],[304.7,304.86],[304.92,305.24],[305.66,305.92],[306.48,306.6],[306.76,307.02]]},{"id":64,"p":37,"en":"Now, in the animal world, that works fine.","zh":"在动物世界里，这样完全没问题。","s":307.86,"e":310.97,"w":[[307.98,308.16],[308.22,308.28],[308.3,308.36],[308.46,308.76],[308.8,309.08],[309.78,309.96],[310.02,310.26],[310.32,310.75]]},{"id":65,"p":37,"en":"If you're a dog and you spend your whole life doing nothing other than easy and fun things, you're a huge success!","zh":"如果你是一只狗，一辈子只做轻松好玩的事，那你就是巨大的成功！","s":310.97,"e":316.64,"w":[[311.09,311.17],[311.19,311.39],[311.51,311.53],[311.53,311.97],[312.29,312.35],[312.37,312.45],[312.49,312.69],[312.69,312.79],[312.81,312.97],[312.99,313.17],[313.21,313.43],[313.49,313.77],[313.85,314.03],[314.09,314.21],[314.37,314.57],[314.63,314.71],[314.77,314.93],[315.01,315.17],[315.19,315.35],[315.51,315.53],[315.53,315.87],[315.91,316.39]]},{"id":66,"p":39,"en":"And to the Monkey, humans are just another animal species.","zh":"在猴子眼里，人类只不过是另一种动物。","s":317.91,"e":323.47,"w":[[318.03,318.13],[319.05,319.13],[319.17,319.23],[319.29,319.63],[321.59,321.87],[321.89,321.97],[321.97,322.15],[322.19,322.59],[322.79,323.05],[323.11,323.55]]},{"id":67,"p":39,"en":"You have to keep well-slept, well-fed and propagating into the next generation, which in tribal times might have worked OK.","zh":"你只要睡好、吃饱、繁衍后代就行，这在部落时代也许还行得通。","s":323.47,"e":330.11,"w":[[323.59,323.67],[323.67,323.75],[323.75,323.79],[323.85,324.03],[324.09,324.25],[324.37,324.73],[324.81,324.97],[325.07,325.31],[325.33,325.43],[325.47,326.12],[326.16,326.3],[326.34,326.4],[326.44,326.64],[326.66,327.26],[328.26,328.38],[328.42,328.48],[328.54,328.92],[328.98,329.3],[329.38,329.52],[329.52,329.62],[329.62,329.82],[329.82,329.86]]},{"id":68,"p":39,"en":"But, if you haven't noticed, now we're not in tribal times.","zh":"可是，你可能没注意到，我们现在已经不在部落时代了。","s":330.4,"e":333.28,"w":[[330.52,330.64],[330.8,330.86],[330.88,330.96],[330.98,331.18],[331.2,331.52],[331.58,331.72],[331.74,331.86],[331.9,332.04],[332.12,332.22],[332.3,332.68],[332.74,333.18]]},{"id":69,"p":39,"en":"We're in an advanced civilization, and the Monkey does not know what that is.","zh":"我们生活在高度发达的文明里，而猴子根本不知道那是什么。","s":333.28,"e":337.47,"w":[[333.4,333.54],[333.56,333.62],[333.76,333.82],[333.86,334.38],[334.52,335.2],[335.26,335.32],[335.34,335.4],[335.44,335.7],[335.76,335.9],[336.0,336.16],[336.22,336.36],[336.4,336.54],[336.6,336.8],[336.96,337.22]]},{"id":70,"p":39,"en":"Which is why we have another guy in our brain, the Rational Decision-Maker, who gives us the ability to do things no other animal can do.","zh":"所以我们的大脑里还有另一个家伙——理性决策者，它让我们能做到其他动物做不到的事。","s":337.48,"e":345.17,"w":[[337.6,337.72],[337.74,337.8],[337.84,337.98],[338.0,338.06],[338.08,338.18],[338.2,338.52],[338.56,338.74],[338.78,338.84],[338.88,338.98],[339.02,339.3],[339.86,339.94],[340.02,340.5],[340.54,340.99],[341.05,341.37],[342.27,342.35],[342.41,342.57],[342.59,342.69],[342.69,342.75],[342.81,343.15],[343.23,343.29],[343.35,343.43],[343.51,343.71],[343.79,343.89],[344.15,344.33],[344.43,344.73],[344.79,344.93],[344.99,345.07]]},{"id":71,"p":39,"en":"We can visualize the future.","zh":"我们能想象未来。","s":345.17,"e":347.13,"w":[[345.29,345.37],[345.45,345.73],[346.11,346.67],[346.67,346.75],[346.79,347.21]]},{"id":72,"p":39,"en":"We can see the big picture.","zh":"我们能看到大局。","s":347.13,"e":348.64,"w":[[347.25,347.31],[347.35,347.45],[347.53,347.65],[347.67,347.73],[347.79,347.93],[347.99,348.39]]},{"id":73,"p":39,"en":"We can make long-term plans.","zh":"我们能做长远的计划。","s":348.89,"e":350.33,"w":[[349.01,349.07],[349.11,349.23],[349.27,349.45],[349.49,349.71],[349.75,349.97],[350.03,350.41]]},{"id":74,"p":39,"en":"And he wants to take all of that into account.","zh":"它想把这些全都考虑进去。","s":350.33,"e":352.7,"w":[[350.45,350.51],[350.53,350.57],[350.61,350.75],[350.77,350.81],[350.85,351.03],[351.15,351.31],[351.37,351.43],[351.47,351.63],[351.69,351.87],[351.95,352.45]]},{"id":75,"p":39,"en":"And he wants to just have us do whatever makes sense to be doing right now.","zh":"它只是想让我们去做此刻最该做的事。","s":353.65,"e":358.29,"w":[[353.77,353.85],[353.87,353.91],[353.97,354.19],[354.23,354.29],[354.43,354.75],[354.81,355.01],[355.03,355.13],[355.25,355.33],[355.41,355.71],[355.81,356.07],[356.26,356.6],[356.66,356.74],[356.78,356.86],[357.02,357.36],[357.48,357.7],[357.74,358.04]]},{"id":76,"p":39,"en":"Now, sometimes it makes sense to be doing things that are easy and fun, like when you're having dinner or going to bed or enjoying well-earned leisure time.","zh":"有时候，做轻松好玩的事是合理的，比如吃晚饭、上床睡觉，或者享受辛苦换来的休闲时光。","s":358.32,"e":365.75,"w":[[358.44,358.54],[358.58,358.94],[358.96,359.0],[359.04,359.2],[359.24,359.58],[359.68,359.74],[359.8,359.86],[360.02,360.26],[360.36,360.7],[360.76,360.88],[360.92,361.04],[361.16,361.4],[361.5,361.6],[361.68,361.86],[361.94,362.12],[362.14,362.24],[362.26,362.38],[362.38,362.62],[362.66,362.9],[363.22,363.28],[363.3,363.5],[363.5,363.56],[363.62,363.84],[363.86,363.92],[363.96,364.3],[364.36,364.56],[364.58,364.86],[364.88,365.18],[365.22,365.5]]},{"id":77,"p":39,"en":"That's why there's an overlap.","zh":"所以这两块会有重叠。","s":365.78,"e":367.28,"w":[[365.9,366.14],[366.18,366.32],[366.36,366.52],[366.54,366.62],[366.66,367.06]]},{"id":78,"p":39,"en":"Sometimes they agree.","zh":"有时候它们意见一致。","s":367.28,"e":368.67,"w":[[367.4,367.9],[367.92,368.04],[368.08,368.42]]},{"id":79,"p":39,"en":"But other times, it makes much more sense to be doing things that are harder and less pleasant, for the sake of the big picture.","zh":"但另一些时候，为了大局，去做更难、更不愉快的事要合理得多。","s":369.04,"e":377.05,"w":[[369.16,369.28],[369.34,369.52],[369.58,370.06],[370.32,370.4],[370.46,370.66],[370.78,370.96],[371.02,371.2],[371.29,371.63],[372.01,372.07],[372.11,372.17],[372.29,372.59],[372.71,373.11],[373.55,373.79],[373.91,374.07],[374.17,374.51],[374.63,374.73],[374.79,374.95],[375.03,375.45],[375.67,375.75],[375.77,375.83],[375.89,376.11],[376.11,376.17],[376.19,376.25],[376.29,376.41],[376.49,376.89]]},{"id":80,"p":39,"en":"And that's when we have a conflict.","zh":"这时候冲突就来了。","s":377.05,"e":378.92,"w":[[377.17,377.27],[377.33,377.63],[377.65,377.75],[377.77,377.81],[377.83,377.93],[377.95,377.97],[378.03,378.67]]},{"id":81,"p":39,"en":"And for the procrastinator, that conflict tends to end a certain way every time,","zh":"而对拖延者来说，这种冲突每次都会以同一种方式收场，","s":379.57,"e":383.37,"w":[[379.69,379.77],[379.81,379.89],[379.89,379.97],[379.99,380.65],[380.67,380.79],[380.85,381.27],[381.29,381.55],[381.57,381.63],[381.73,381.87],[381.91,381.93],[382.01,382.29],[382.33,382.45],[382.55,382.73],[382.81,383.21]]},{"id":82,"p":39,"en":"leaving him spending a lot of time in this orange zone, an easy and fun place that's entirely out of the Makes Sense circle.","zh":"让他把大量时间花在这片橙色区域——一个轻松好玩、却完全不在“合理”圈子里的地方。","s":383.37,"e":391.56,"w":[[383.49,383.75],[383.79,383.89],[383.95,384.31],[384.35,384.37],[384.43,384.59],[384.61,384.67],[384.71,384.99],[385.09,385.17],[385.27,385.45],[385.67,385.99],[386.03,386.41],[387.3,387.46],[387.7,387.98],[388.18,388.3],[388.38,388.56],[388.64,388.9],[388.92,389.06],[389.1,389.72],[389.88,390.08],[390.1,390.16],[390.18,390.24],[390.32,390.6],[390.68,390.96],[391.04,391.36]]},{"id":83,"p":39,"en":"I call it the Dark Playground.","zh":"我把它叫作“黑暗游乐场”。","s":391.56,"e":393.61,"w":[[391.68,391.7],[391.76,391.94],[391.96,392.02],[392.2,392.28],[392.38,392.64],[392.76,393.36]]},{"id":84,"p":41,"en":"Now, the Dark Playground is a place that all of you procrastinators out there know very well.","zh":"在座所有拖延的朋友们，对这个黑暗游乐场都非常熟悉。","s":395.46,"e":401.84,"w":[[395.58,395.8],[397.4,397.46],[397.5,397.72],[397.78,398.18],[398.2,398.28],[398.3,398.32],[398.38,398.64],[398.66,398.78],[398.96,399.36],[399.42,399.48],[399.52,399.62],[399.66,400.42],[400.48,400.6],[400.64,400.78],[400.84,400.96],[401.04,401.28],[401.36,401.59]]},{"id":85,"p":41,"en":"It's where leisure activities happen at times when leisure activities are not supposed to be happening.","zh":"在那里，休闲活动发生在本不该休闲的时候。","s":402.37,"e":407.44,"w":[[402.49,402.63],[402.65,402.83],[402.89,403.19],[403.23,403.69],[403.75,404.09],[404.15,404.23],[404.29,404.61],[404.63,404.73],[404.79,405.09],[405.15,405.63],[405.65,405.75],[405.79,405.99],[406.07,406.49],[406.51,406.55],[406.59,406.65],[406.73,407.19]]},{"id":86,"p":41,"en":"The fun you have in the Dark Playground isn't actually fun, because it's completely unearned, and","zh":"你在黑暗游乐场里的快乐其实并不快乐，因为那完全不是你挣来的，","s":407.91,"e":411.77,"w":[[408.03,408.09],[408.15,408.33],[408.39,408.49],[408.55,408.77],[408.79,408.83],[408.85,408.91],[408.95,409.13],[409.17,409.45],[409.49,409.65],[409.71,410.03],[410.09,410.29],[410.35,410.61],[410.61,410.73],[410.77,411.25],[411.33,411.79],[411.81,411.87]]},{"id":87,"p":41,"en":"the air is filled with guilt, dread, anxiety, self-hatred -- all of those good procrastinator feelings.","zh":"空气里弥漫着内疚、恐惧、焦虑、自我厌恶——拖延者那一整套“美好”感受。","s":411.77,"e":417.61,"w":[[411.89,411.95],[412.03,412.15],[412.21,412.27],[412.33,412.51],[412.53,412.65],[412.75,413.05],[413.49,413.95],[414.27,414.75],[414.85,415.05],[415.09,415.45],[415.51,415.61],[415.61,415.65],[415.65,415.83],[415.89,416.09],[416.13,416.84],[416.88,417.36]]},{"id":88,"p":41,"en":"And the question is, in this situation, with the Monkey behind the wheel,","zh":"问题在于，在这种情况下，猴子握着方向盘，","s":418.22,"e":421.46,"w":[[418.34,418.4],[418.42,418.48],[418.5,418.84],[418.88,418.96],[419.0,419.04],[419.08,419.2],[419.3,419.96],[420.08,420.18],[420.2,420.26],[420.28,420.54],[420.6,420.86],[420.88,420.96],[420.98,421.24]]},{"id":89,"p":41,"en":"how does the procrastinator ever get himself over here to this blue zone, a less pleasant place, but where really important things happen?","zh":"拖延者究竟怎样才能到达这片蓝色区域？那是个不太愉快、却真正发生重要事情的地方。","s":421.46,"e":428.25,"w":[[421.58,421.68],[421.68,421.8],[421.8,421.88],[421.88,422.5],[422.58,422.8],[423.12,423.24],[423.24,423.54],[423.62,423.76],[423.8,423.96],[423.96,424.0],[424.04,424.16],[424.3,424.58],[424.66,425.04],[425.42,425.44],[425.52,425.7],[425.78,426.12],[426.16,426.42],[426.46,426.56],[426.58,426.72],[426.76,427.0],[427.06,427.5],[427.52,427.68],[427.7,428.0]]},{"id":90,"p":42,"en":"Well, turns out the procrastinator has a guardian angel, someone who's always looking down on him and watching over him in his darkest moments -- someone called the Panic Monster.","zh":"原来，拖延者有一位守护天使，它一直俯视着他，在他最黑暗的时刻守护着他——它叫“恐慌怪兽”。","s":428.62,"e":440.56,"w":[[428.74,428.92],[429.86,430.12],[430.2,430.44],[430.96,431.16],[431.18,431.97],[432.15,432.53],[432.71,432.73],[432.85,433.23],[433.29,433.59],[433.79,433.97],[433.97,434.09],[434.19,434.53],[434.57,434.81],[434.85,435.11],[435.17,435.27],[435.33,435.47],[435.53,435.61],[435.67,436.01],[436.05,436.23],[436.29,436.45],[437.07,437.13],[437.15,437.25],[437.29,437.63],[437.67,438.07],[438.43,438.69],[438.71,438.99],[439.13,439.21],[439.29,439.73],[439.87,440.31]]},{"id":91,"p":44,"en":"Now, the Panic Monster is dormant most of the time, but","zh":"恐慌怪兽大部分时间都在沉睡，可是","s":445.93,"e":450.88,"w":[[446.05,446.27],[447.32,447.4],[447.46,447.9],[448.0,448.46],[448.68,448.76],[448.82,449.2],[449.26,449.46],[449.5,449.54],[449.56,449.64],[449.66,449.96],[450.88,450.98]]},{"id":92,"p":44,"en":"he suddenly wakes up anytime a deadline gets too close or there's danger of public embarrassment, a career disaster or some other scary consequence.","zh":"每当截止日期逼得太近，或者有当众出丑、事业受挫或其他可怕后果的危险时，它就会突然醒来。","s":450.88,"e":459.38,"w":[[451.0,451.04],[451.16,451.5],[451.58,451.86],[451.92,452.08],[452.82,453.4],[453.46,453.48],[453.56,453.96],[454.0,454.16],[454.2,454.32],[454.34,454.68],[454.82,454.92],[454.98,455.16],[455.2,455.48],[455.52,455.56],[455.62,455.9],[455.94,456.56],[456.86,456.88],[456.94,457.24],[457.28,457.72],[457.72,457.76],[457.82,457.94],[457.96,458.1],[458.16,458.46],[458.54,459.2]]},{"id":93,"p":44,"en":"And importantly, he's the only thing the Monkey is terrified of.","zh":"重要的是，它是猴子唯一害怕的东西。","s":459.38,"e":463.53,"w":[[459.5,459.6],[459.62,460.2],[460.38,460.56],[460.62,460.7],[460.9,461.26],[461.4,461.66],[461.7,461.88],[461.92,462.21],[462.29,462.37],[462.55,463.15],[463.21,463.33]]},{"id":94,"p":44,"en":"Now, he became very relevant in my life pretty recently, because the people of TED reached out to me about six months ago and invited me to do a TED Talk.","zh":"最近它和我的生活关系可大了，因为大约六个月前，TED 的人联系我，邀请我来做 TED 演讲。","s":463.53,"e":473.34,"w":[[463.65,463.85],[464.55,464.61],[464.67,464.95],[464.97,465.19],[465.27,465.65],[465.67,465.73],[465.75,465.85],[465.93,466.21],[466.57,466.81],[466.91,467.41],[468.19,468.47],[468.47,468.53],[468.55,468.81],[468.83,468.87],[468.97,469.29],[469.77,470.05],[470.09,470.23],[470.27,470.33],[470.39,470.45],[470.53,470.81],[470.89,471.03],[471.11,471.31],[471.35,471.49],[471.55,471.63],[471.65,472.03],[472.07,472.13],[472.19,472.23],[472.29,472.37],[472.43,472.45],[472.53,472.73],[472.83,473.09]]},{"id":95,"p":46,"en":"Now, of course, I said yes.","zh":"我当然答应了。","s":478.6,"e":480.42,"w":[[478.72,478.86],[479.02,479.06],[479.14,480.06],[480.06,480.08],[480.08,480.2],[480.26,480.5]]},{"id":96,"p":46,"en":"It's always been a dream of mine to have done a TED Talk in the past.","zh":"一直以来，“做过一次 TED 演讲”都是我的梦想。","s":480.42,"e":484.39,"w":[[480.54,480.64],[480.72,480.92],[480.96,481.08],[481.1,481.12],[481.18,481.38],[481.4,481.46],[481.52,481.72],[481.74,481.82],[481.92,482.24],[482.36,482.62],[482.66,482.68],[482.76,482.96],[483.02,483.26],[483.36,483.42],[483.44,483.52],[483.56,484.14]]},{"id":97,"p":48,"en":"But in the middle of all this excitement, the Rational Decision-Maker seemed to have something else on his mind.","zh":"可就在一片兴奋之中，理性决策者好像在想别的事。","s":495.69,"e":499.39,"w":[[495.81,495.89],[495.91,495.95],[495.97,496.03],[496.03,496.21],[496.23,496.27],[496.31,496.39],[496.41,496.53],[496.57,496.93],[496.95,497.01],[497.05,497.39],[497.41,497.77],[497.79,498.03],[498.09,498.27],[498.27,498.33],[498.33,498.49],[498.51,498.75],[498.79,498.95],[498.97,499.03],[499.05,499.15],[499.19,499.43]]},{"id":98,"p":48,"en":"He was saying, \"Are we clear on what we just accepted?","zh":"它在说：“我们清楚自己刚刚答应了什么吗？","s":499.39,"e":503.4,"w":[[499.51,499.55],[499.61,499.69],[499.75,499.99],[500.53,500.61],[500.61,500.71],[500.87,501.33],[501.77,501.85],[501.93,502.07],[502.17,502.25],[502.33,502.53],[502.57,503.15]]},{"id":99,"p":48,"en":"Do we get what's going to be now happening one day in the future?","zh":"我们明白将来某一天会发生什么吗？","s":503.69,"e":506.91,"w":[[503.81,503.87],[503.89,503.95],[504.11,504.39],[504.93,505.11],[505.15,505.39],[505.41,505.47],[505.49,505.55],[505.63,505.81],[505.89,506.29],[506.33,506.43],[506.45,506.55],[506.59,506.63],[506.65,506.71],[506.73,507.01]]},{"id":100,"p":48,"en":"We need to sit down and work on this right now.\"","zh":"我们现在就得坐下来开始准备。”","s":506.91,"e":509.13,"w":[[507.03,507.07],[507.11,507.21],[507.23,507.29],[507.33,507.45],[507.47,507.61],[507.61,507.7],[507.72,507.88],[507.94,508.0],[508.02,508.16],[508.28,508.5],[508.58,508.88]]},{"id":101,"p":48,"en":"And the Monkey said, \"Totally agree, but let's just open Google Earth and zoom in to the bottom of India, like 200 feet above the ground, and","zh":"猴子说：“完全同意，不过我们先打开谷歌地球，放大到印度最南端，离地面大概两百英尺，","s":509.18,"e":515.38,"w":[[509.3,509.36],[509.36,509.42],[509.46,509.74],[509.84,509.98],[510.2,510.54],[510.6,510.82],[510.84,510.94],[511.04,511.34],[511.36,511.5],[511.56,511.74],[511.8,512.06],[512.12,512.3],[512.56,512.64],[512.82,512.94],[512.98,513.04],[513.06,513.12],[513.16,513.22],[513.3,513.56],[513.6,513.66],[513.78,514.02],[514.06,514.2],[514.22,514.34],[514.34,514.5],[514.52,514.66],[514.7,514.86],[514.88,514.94],[514.96,515.18],[515.2,515.26]]},{"id":102,"p":48,"en":"scroll up for two and a half hours til we get to the top of the country, so we can get a better feel for India.\"","zh":"然后往上滚动两个半小时，一直滚到这个国家的最北端，这样我们就能更好地感受印度。”","s":515.38,"e":520.81,"w":[[515.5,515.76],[515.78,515.84],[515.88,515.96],[516.0,516.16],[516.18,516.26],[516.26,516.28],[516.32,516.52],[516.6,516.9],[517.18,517.26],[517.28,517.32],[517.36,517.46],[517.48,517.54],[517.56,517.64],[517.7,517.94],[518.0,518.06],[518.1,518.16],[518.2,518.48],[518.52,518.6],[518.64,518.7],[518.72,518.84],[518.88,518.98],[519.0,519.02],[519.1,519.3],[519.48,519.84],[519.98,520.12],[520.22,520.56]]},{"id":103,"p":50,"en":"So that's what we did that day.","zh":"那天我们就是这么过的。","s":526.63,"e":528.26,"w":[[526.75,526.83],[526.91,527.13],[527.17,527.27],[527.29,527.35],[527.43,527.57],[527.61,527.77],[527.83,528.01]]},{"id":104,"p":52,"en":"As six months turned into four and then two and then one, the people of TED decided to release the speakers.","zh":"六个月变成四个月，又变成两个月、一个月，TED 公布了演讲者名单。","s":532.29,"e":539.17,"w":[[532.41,532.51],[532.61,532.73],[532.89,533.17],[533.21,533.51],[533.55,533.71],[533.83,534.15],[534.27,534.35],[534.37,534.51],[534.63,534.89],[535.03,535.17],[535.21,535.45],[535.71,535.93],[536.13,536.21],[536.25,536.51],[536.55,536.61],[536.67,536.85],[536.87,537.25],[537.29,537.37],[537.53,538.02],[538.3,538.38],[538.44,538.92]]},{"id":105,"p":52,"en":"And I opened up the website, and there was my face staring right back at me.","zh":"我打开网站，我自己的脸正盯着我看。","s":539.2,"e":543.1,"w":[[539.32,539.4],[539.48,539.5],[539.58,539.8],[539.82,539.9],[539.92,539.98],[540.06,540.56],[540.76,540.84],[540.84,540.98],[540.98,541.08],[541.12,541.24],[541.32,541.68],[541.9,542.18],[542.22,542.4],[542.42,542.62],[542.66,542.74],[542.8,542.88]]},{"id":106,"p":52,"en":"And guess who woke up?","zh":"猜猜谁醒了？","s":543.1,"e":544.61,"w":[[543.22,543.32],[543.52,543.7],[543.76,543.84],[543.92,544.18],[544.22,544.36]]},{"id":107,"p":54,"en":"So the Panic Monster starts losing his mind, and a few seconds later, the whole system's in mayhem.","zh":"于是恐慌怪兽开始抓狂，几秒钟后整个系统一片混乱。","s":548.92,"e":553.94,"w":[[549.04,549.1],[549.16,549.22],[549.26,549.6],[549.66,550.02],[550.06,550.3],[550.36,550.62],[550.64,550.74],[550.8,551.14],[551.54,551.62],[551.62,551.64],[551.7,551.82],[551.86,552.12],[552.14,552.32],[552.5,552.56],[552.58,552.74],[552.8,553.21],[553.23,553.29],[553.33,553.69]]},{"id":108,"p":56,"en":"And the Monkey -- remember, he's terrified of the Panic Monster -- boom, he's up the tree!","zh":"而猴子——记住，它怕恐慌怪兽——砰的一下，就窜上了树！","s":559.03,"e":562.76,"w":[[559.15,559.25],[559.25,559.31],[559.35,559.61],[559.73,560.05],[560.09,560.21],[560.29,560.79],[560.81,560.85],[560.87,560.93],[560.95,561.17],[561.21,561.45],[561.57,561.77],[561.85,561.99],[562.03,562.11],[562.15,562.23],[562.27,562.51]]},{"id":109,"p":56,"en":"And finally, finally, the Rational Decision-Maker can take the wheel and I can start working on the talk.","zh":"终于，终于，理性决策者能握住方向盘，我也能开始准备演讲了。","s":563.19,"e":568.74,"w":[[563.31,563.41],[563.55,563.99],[564.51,564.99],[565.35,565.41],[565.45,565.81],[565.83,566.09],[566.11,566.29],[566.31,566.41],[566.45,566.63],[566.65,566.71],[566.75,566.99],[567.15,567.23],[567.31,567.33],[567.35,567.45],[567.51,567.71],[567.75,567.99],[568.01,568.07],[568.09,568.15],[568.21,568.56]]},{"id":110,"p":57,"en":"Now, the Panic Monster explains all kinds of pretty insane procrastinator behavior, like how someone like me could spend two weeks unable to start the opening sentence of a paper, and","zh":"恐慌怪兽解释了拖延者各种相当疯狂的行为，比如像我这样的人，可以两周都写不出论文的第一句话，","s":568.74,"e":581.0,"w":[[568.86,569.08],[569.56,569.64],[569.68,569.92],[570.06,570.38],[570.42,570.86],[571.32,571.64],[571.74,572.14],[572.22,572.32],[573.14,573.3],[573.36,573.76],[573.8,574.36],[574.38,574.72],[574.76,574.92],[574.94,575.04],[575.12,575.36],[575.38,575.54],[575.58,575.64],[575.72,575.84],[575.84,576.02],[576.12,576.36],[576.42,576.68],[577.16,577.68],[578.02,578.14],[578.28,578.66],[578.88,578.96],[579.02,579.32],[579.38,579.64],[579.66,579.72],[579.74,579.76],[579.82,580.18],[581.02,581.1]]},{"id":111,"p":57,"en":"then miraculously find the unbelievable work ethic to stay up all night and write eight pages.","zh":"然后又奇迹般地爆发出惊人的干劲，熬一整夜写出八页。","s":581.0,"e":586.7,"w":[[581.12,581.22],[581.26,581.86],[581.9,582.14],[582.16,582.24],[582.34,582.92],[583.32,583.49],[583.55,583.73],[583.75,583.79],[583.83,583.97],[584.23,584.33],[584.73,584.87],[584.93,585.15],[585.19,585.27],[585.43,585.67],[585.79,585.91],[585.99,586.45]]},{"id":112,"p":57,"en":"And this entire situation, with the three characters -- this is the procrastinator's system.","zh":"整个这套情况，加上这三个角色——就是拖延者的系统。","s":587.95,"e":593.04,"w":[[588.07,588.33],[588.59,588.83],[588.99,589.37],[589.45,589.91],[589.95,590.03],[590.05,590.11],[590.19,590.45],[590.63,591.07],[591.11,591.25],[591.31,591.37],[591.41,591.49],[591.51,592.35],[592.47,592.79]]},{"id":113,"p":57,"en":"It's not pretty, but in the end, it works.","zh":"它不好看，但最终是管用的。","s":593.57,"e":596.88,"w":[[593.69,593.77],[593.83,593.99],[594.07,594.29],[594.61,594.71],[594.75,594.83],[594.89,594.97],[595.05,595.31],[596.21,596.27],[596.29,596.63]]},{"id":114,"p":57,"en":"This is what I decided to write about on the blog a couple of years ago.","zh":"这就是几年前我决定在博客上写的内容。","s":597.17,"e":601.11,"w":[[597.29,597.43],[597.47,597.55],[597.61,597.73],[597.79,597.81],[597.83,598.15],[598.17,598.23],[598.27,598.49],[598.51,598.8],[599.06,599.14],[599.16,599.24],[599.28,599.66],[600.22,600.24],[600.28,600.46],[600.46,600.5],[600.52,600.68],[600.7,600.86]]},{"id":115,"p":58,"en":"When I did, I was amazed by the response.","zh":"写出来之后，大家的反应让我很吃惊。","s":601.16,"e":604.1,"w":[[601.28,601.48],[601.56,601.6],[601.66,601.88],[602.68,602.7],[602.72,602.8],[602.82,603.2],[603.22,603.3],[603.32,603.38],[603.42,603.86]]},{"id":116,"p":58,"en":"Literally thousands of emails came in, from all different kinds of people from all over the world, doing all different kinds of things.","zh":"真的有成千上万封邮件涌进来，来自世界各地、各行各业的人。","s":604.1,"e":610.37,"w":[[604.22,604.48],[604.6,605.06],[605.08,605.12],[605.18,605.44],[605.5,605.68],[605.7,605.8],[606.36,606.48],[606.62,606.76],[606.76,606.96],[606.96,607.14],[607.16,607.2],[607.22,607.48],[607.66,607.78],[607.9,608.02],[608.06,608.2],[608.2,608.28],[608.3,608.54],[608.56,608.74],[608.8,608.9],[608.92,609.16],[609.18,609.42],[609.44,609.5],[609.64,610.12]]},{"id":117,"p":58,"en":"These are people who were nurses, bankers, painters, engineers and lots and lots of PhD students.","zh":"他们有护士、银行家、画家、工程师，还有非常非常多的博士生。","s":610.4,"e":616.04,"w":[[610.52,610.64],[610.68,610.76],[610.76,611.0],[611.02,611.08],[611.1,611.22],[611.3,611.82],[612.04,612.6],[612.78,613.28],[613.38,613.77],[613.79,613.87],[613.97,614.33],[614.37,614.45],[614.49,614.75],[614.77,614.83],[614.85,615.23],[615.37,615.79]]},{"id":118,"p":60,"en":"And they were all writing, saying the same thing: \"I have this problem too.\"","zh":"他们都写了同一句话：“我也有这个问题。”","s":618.23,"e":622.26,"w":[[618.35,618.43],[618.43,618.51],[618.51,618.63],[618.69,618.81],[618.85,619.17],[619.23,619.41],[619.41,619.47],[619.51,619.73],[619.75,619.93],[620.41,620.43],[620.61,620.91],[620.97,621.13],[621.21,621.61],[621.75,622.01]]},{"id":119,"p":60,"en":"But what struck me was the contrast between the light tone of the post and the heaviness of these emails.","zh":"但让我震动的是：文章的语气很轻松，而这些邮件却很沉重，两者形成了强烈的反差。","s":622.47,"e":628.16,"w":[[622.59,622.67],[622.67,622.77],[622.81,623.05],[623.11,623.15],[623.19,623.29],[623.29,623.37],[623.39,623.87],[623.89,624.13],[624.13,624.21],[624.31,624.57],[624.75,624.99],[625.01,625.07],[625.09,625.15],[625.19,625.59],[626.51,626.59],[626.61,626.67],[626.73,627.09],[627.13,627.19],[627.23,627.39],[627.43,627.91]]},{"id":120,"p":60,"en":"These people were writing with intense frustration about what procrastination had done to their lives, about what this Monkey had done to them.","zh":"这些人带着强烈的挫败感，写下拖延症对他们的生活做了什么，这只猴子对他们做了什么。","s":628.47,"e":636.49,"w":[[628.59,628.77],[628.81,629.16],[629.82,629.98],[630.44,630.7],[630.7,630.8],[630.82,631.18],[631.22,631.72],[631.76,632.0],[632.22,632.34],[632.46,633.16],[633.16,633.26],[633.32,633.48],[633.5,633.56],[633.6,633.72],[633.78,634.18],[634.48,634.66],[634.68,634.78],[634.82,634.94],[635.06,635.38],[635.54,635.66],[635.72,635.92],[635.96,636.02],[636.06,636.24]]},{"id":121,"p":60,"en":"And I thought about this, and I said, well, if the procrastinator's system works, then what's going on?","zh":"我想了想，就说：好吧，如果拖延者的系统是管用的，那到底出了什么问题？","s":638.48,"e":644.4,"w":[[638.6,639.04],[640.18,640.2],[640.24,640.44],[640.48,640.7],[640.76,640.98],[641.24,641.32],[641.38,641.4],[641.42,641.54],[641.54,641.64],[641.66,641.7],[641.74,641.8],[641.8,642.4],[642.42,642.66],[642.76,643.04],[643.3,643.4],[643.42,643.58],[643.62,643.84],[643.9,644.15]]},{"id":122,"p":60,"en":"Why are all of these people in such a dark place?","zh":"为什么这些人都陷在这么黑暗的地方？","s":644.49,"e":646.11,"w":[[644.61,644.77],[644.81,644.87],[644.87,644.95],[644.95,644.99],[644.99,645.11],[645.11,645.33],[645.35,645.39],[645.43,645.55],[645.57,645.59],[645.63,645.83],[645.87,646.17]]},{"id":123,"p":61,"en":"Well, it turns out that there's two kinds of procrastination.","zh":"原来，拖延有两种。","s":646.11,"e":650.48,"w":[[646.23,646.41],[647.09,647.15],[647.17,647.41],[647.47,647.63],[647.65,647.75],[647.79,647.97],[648.11,648.37],[648.83,649.19],[649.21,649.27],[649.29,650.23]]},{"id":124,"p":61,"en":"Everything I've talked about today, the examples I've given, they all have deadlines.","zh":"今天我讲的所有内容、举的所有例子，都是有截止日期的。","s":651.51,"e":654.27,"w":[[651.63,651.85],[651.85,651.95],[651.95,652.19],[652.19,652.35],[652.37,652.57],[652.61,652.67],[652.71,653.05],[653.07,653.17],[653.19,653.37],[653.37,653.47],[653.51,653.59],[653.63,653.79],[653.89,654.37]]},{"id":125,"p":61,"en":"And when there's deadlines, the effects of procrastination are contained to the short term because the Panic Monster gets involved.","zh":"有截止日期的时候，拖延的影响只限于短期，因为恐慌怪兽会出场。","s":654.27,"e":661.02,"w":[[654.39,654.45],[654.45,654.53],[654.55,654.69],[654.75,655.43],[655.69,655.77],[655.83,656.19],[656.21,656.27],[656.29,656.97],[657.03,657.11],[657.15,658.01],[658.57,658.63],[658.65,658.71],[658.79,659.01],[659.07,659.3],[659.36,659.64],[659.68,659.74],[659.78,660.1],[660.12,660.38],[660.4,660.56],[660.58,660.94]]},{"id":126,"p":61,"en":"But there's a second kind of procrastination that happens in situations when there is no deadline.","zh":"但还有第二种拖延，发生在没有截止日期的情况下。","s":661.02,"e":666.16,"w":[[661.14,661.2],[661.22,661.36],[661.4,661.42],[661.5,661.76],[661.8,661.96],[661.98,662.02],[662.04,662.82],[663.1,663.2],[663.26,663.64],[663.66,663.74],[663.82,664.6],[664.8,664.9],[664.92,665.04],[665.12,665.26],[665.34,665.42],[665.58,666.04]]},{"id":127,"p":61,"en":"So if you wanted a career where you're a self-starter -- something in the arts, something entrepreneurial --","zh":"比如你想要一份需要自我驱动的事业——搞艺术、去创业——","s":666.16,"e":671.33,"w":[[666.28,666.36],[666.72,666.76],[666.78,666.84],[666.84,667.0],[667.06,667.08],[667.22,667.46],[667.46,667.56],[667.56,667.76],[667.82,667.84],[667.92,668.1],[668.2,668.6],[668.66,668.88],[668.9,668.94],[668.96,669.02],[669.18,669.52],[669.58,669.86],[670.48,671.08]]},{"id":128,"p":61,"en":"there's no deadlines on those things at first, because nothing's happening, not until you've gone out and done the hard work to get momentum, get things going.","zh":"这些事一开始都没有截止日期，因为什么都还没发生，直到你出去下苦功、积累起势头，事情才会动起来。","s":671.34,"e":678.86,"w":[[671.46,671.6],[671.62,671.68],[671.8,672.22],[672.24,672.32],[672.34,672.5],[672.5,672.68],[672.7,672.78],[672.82,673.16],[673.52,673.74],[673.76,674.0],[674.06,674.53],[674.99,675.11],[675.15,675.41],[675.49,675.67],[675.71,675.89],[675.93,676.03],[676.03,676.11],[676.13,676.27],[676.27,676.33],[676.37,676.55],[676.61,676.77],[676.81,676.87],[676.91,677.03],[677.15,677.71],[677.85,677.95],[678.05,678.27],[678.33,678.61]]},{"id":129,"p":61,"en":"There's also all kinds of important things outside of your career that don't involve any deadlines,","zh":"事业之外，还有各种重要的事情也没有任何截止日期，","s":678.87,"e":682.89,"w":[[678.99,679.13],[679.13,679.29],[679.35,679.47],[679.49,679.71],[679.71,679.75],[679.79,680.13],[680.15,680.31],[680.43,680.75],[680.77,680.81],[680.85,680.95],[680.99,681.27],[681.51,681.63],[681.71,681.91],[681.93,682.27],[682.29,682.39],[682.49,682.99]]},{"id":130,"p":61,"en":"like seeing your family or exercising and taking care of your health, working on your relationship or getting out of a relationship that isn't working.","zh":"比如去看望家人、锻炼身体、照顾健康、经营感情，或者离开一段不合适的关系。","s":682.89,"e":690.33,"w":[[683.01,683.17],[683.21,683.43],[683.43,683.53],[683.55,683.91],[683.99,684.05],[684.15,684.81],[684.81,684.89],[684.91,685.13],[685.17,685.33],[685.35,685.41],[685.45,685.55],[685.59,685.97],[686.79,687.07],[687.09,687.15],[687.17,687.27],[687.29,687.85],[687.95,688.05],[688.43,688.65],[688.73,688.87],[688.89,688.95],[688.97,688.99],[689.05,689.49],[689.52,689.6],[689.64,689.84],[689.88,690.08]]},{"id":131,"p":62,"en":"Now if the procrastinator's only mechanism of doing these hard things is the Panic Monster,","zh":"如果拖延者做这些难事的唯一机制就是恐慌怪兽，","s":691.08,"e":697.16,"w":[[691.2,691.36],[691.56,691.7],[692.28,692.34],[692.34,693.0],[693.1,693.28],[693.38,693.98],[694.66,694.74],[694.86,695.12],[695.16,695.34],[695.38,695.62],[695.7,696.12],[696.4,696.46],[696.5,696.58],[696.6,696.88],[696.94,697.24]]},{"id":132,"p":62,"en":"that's a problem, because in all of these non-deadline situations, the Panic Monster doesn't show up.","zh":"那就麻烦了，因为在这些没有截止日期的情况下，恐慌怪兽根本不会出现。","s":697.16,"e":702.28,"w":[[697.28,697.44],[697.48,697.5],[697.56,697.86],[697.86,698.04],[698.04,698.12],[698.28,698.42],[698.48,698.54],[698.56,698.72],[698.76,699.0],[699.06,699.46],[699.52,700.26],[701.0,701.08],[701.1,701.36],[701.42,701.72],[701.76,702.0],[702.06,702.2],[702.26,702.38]]},{"id":133,"p":62,"en":"He has nothing to wake up for, so the effects of procrastination, they're not contained; they just extend outward forever.","zh":"它没有醒来的理由，所以拖延的影响不再受限，而是无止境地向外蔓延。","s":702.28,"e":708.1,"w":[[702.4,702.46],[702.46,702.52],[702.54,702.74],[702.74,702.78],[702.82,702.98],[703.02,703.1],[703.2,703.42],[703.92,704.0],[704.06,704.14],[704.16,704.46],[704.48,704.52],[704.54,705.17],[705.19,705.33],[705.35,705.47],[705.53,705.91],[705.91,705.99],[706.01,706.15],[706.17,706.47],[706.65,707.09],[707.43,707.85]]},{"id":134,"p":62,"en":"And it's this long-term kind of procrastination that's much less visible and much less talked about than the funnier, short-term deadline-based kind.","zh":"正是这种长期的拖延，比那种更好笑的、短期的、有截止日期的拖延隐蔽得多，也很少被人谈起。","s":709.47,"e":718.25,"w":[[709.59,709.67],[709.67,709.77],[709.83,709.95],[710.05,710.27],[710.33,710.51],[710.57,710.77],[710.77,710.81],[710.83,711.71],[712.31,712.55],[712.65,712.83],[712.91,713.05],[713.19,713.61],[714.03,714.09],[714.13,714.31],[714.39,714.53],[714.69,715.05],[715.09,715.33],[715.35,715.45],[715.47,715.53],[715.67,716.05],[716.17,716.41],[716.51,716.73],[716.87,717.33],[717.37,717.65],[717.71,718.05]]},{"id":135,"p":62,"en":"It's usually suffered quietly and privately.","zh":"人们通常默默地、独自承受它。","s":718.25,"e":721.07,"w":[[718.37,718.47],[718.51,718.73],[718.79,719.07],[719.11,719.69],[720.14,720.22],[720.28,720.82]]},{"id":136,"p":62,"en":"And it can be the source of a huge amount of long-term unhappiness, and regrets.","zh":"它可能带来大量长期的不快乐和遗憾。","s":722.36,"e":726.91,"w":[[722.48,722.56],[722.58,722.64],[722.72,722.8],[722.82,722.86],[722.9,722.96],[723.02,723.26],[723.28,723.34],[723.36,723.38],[723.48,723.72],[723.74,723.96],[723.98,724.04],[724.12,724.34],[724.38,724.62],[724.82,725.58],[726.02,726.12],[726.18,726.66]]},{"id":137,"p":62,"en":"And I thought, that's why those people are emailing, and that's why they're in such a bad place.","zh":"我想，这就是那些人写邮件的原因，也是他们处境这么糟糕的原因。","s":728.08,"e":733.15,"w":[[728.2,728.3],[728.36,728.38],[728.42,728.64],[728.86,729.12],[729.16,729.36],[729.42,729.62],[729.66,730.02],[730.28,730.4],[730.48,730.92],[731.0,731.1],[731.12,731.32],[731.34,731.5],[731.56,731.74],[731.76,731.82],[731.92,732.1],[732.12,732.14],[732.2,732.44],[732.52,732.9]]},{"id":138,"p":62,"en":"It's not that they're cramming for some project.","zh":"不是因为他们在为某个项目临时抱佛脚。","s":733.32,"e":736.37,"w":[[733.44,733.58],[733.62,733.76],[733.8,733.92],[734.08,734.22],[734.26,734.64],[734.66,734.76],[734.8,734.96],[735.65,736.17]]},{"id":139,"p":62,"en":"It's that long-term procrastination has made them feel like a spectator, at times, in their own lives.","zh":"而是长期的拖延让他们有时觉得，自己只是自己人生的旁观者。","s":736.37,"e":741.72,"w":[[736.49,736.61],[736.63,736.77],[736.89,737.15],[737.19,737.35],[737.37,737.99],[738.01,738.09],[738.13,738.27],[738.27,738.35],[738.37,738.49],[738.51,738.61],[738.63,738.65],[738.77,739.39],[739.57,739.63],[739.69,739.99],[740.09,740.17],[740.21,740.35],[740.49,740.71],[740.93,741.47]]},{"id":140,"p":62,"en":"The frustration is not that they couldn't achieve their dreams; it's that they weren't even able to start chasing them.","zh":"让人沮丧的不是他们没能实现梦想，而是他们连追梦都还没开始。","s":742.31,"e":747.8,"w":[[742.43,742.49],[742.53,743.21],[743.53,743.59],[743.65,743.79],[743.83,743.91],[743.93,744.01],[744.07,744.29],[744.31,744.61],[744.63,744.73],[744.77,744.99],[744.99,745.07],[745.11,745.21],[745.25,745.37],[745.41,745.61],[745.63,745.77],[745.87,746.07],[746.09,746.15],[746.27,746.67],[746.97,747.39],[747.41,747.55]]},{"id":141,"p":63,"en":"So I read these emails and I had a little bit of an epiphany -- that I don't think non-procrastinators exist.","zh":"所以读了这些邮件，我有了一点顿悟——我认为根本不存在不拖延的人。","s":748.19,"e":757.15,"w":[[748.31,748.41],[749.55,749.57],[750.3,750.44],[750.46,750.62],[750.66,750.9],[750.9,750.98],[751.02,751.04],[751.08,751.2],[751.22,751.24],[751.28,751.44],[751.44,751.54],[751.56,751.6],[751.62,751.68],[751.68,752.1],[753.82,754.04],[754.64,754.66],[754.7,754.86],[754.9,755.04],[755.1,755.3],[755.34,756.18],[756.34,756.9]]},{"id":142,"p":63,"en":"That's right -- I think all of you are procrastinators.","zh":"没错——我认为你们所有人都是拖延者。","s":757.48,"e":760.63,"w":[[757.6,757.76],[757.8,757.98],[758.48,758.52],[758.56,758.72],[759.0,759.18],[759.22,759.28],[759.32,759.4],[759.46,759.54],[759.54,760.38]]},{"id":143,"p":63,"en":"Now, you might not all be a mess, like some of us,","zh":"也许你们不会都像我们中的某些人这样一团糟，","s":761.4,"e":764.41,"w":[[761.52,761.62],[761.66,761.72],[761.74,761.88],[761.9,762.0],[762.08,762.2],[762.22,762.3],[762.36,762.38],[762.54,762.86],[763.4,763.58],[763.7,763.86],[763.9,763.96],[764.0,764.16]]},{"id":144,"p":65,"en":"and some of you may have a healthy relationship with deadlines, but remember: the Monkey's sneakiest trick is when the deadlines aren't there.","zh":"有些人也许和截止日期相处得很好，但请记住：猴子最狡猾的伎俩，就是在没有截止日期的时候出手。","s":766.29,"e":774.06,"w":[[766.41,766.53],[766.63,766.79],[766.81,766.87],[766.89,766.99],[767.03,767.15],[767.25,767.45],[767.49,767.51],[767.57,767.83],[767.91,768.39],[768.41,768.53],[768.59,769.27],[769.69,769.79],[769.83,770.21],[770.29,770.35],[770.43,770.81],[770.99,771.75],[771.97,772.25],[772.31,772.39],[772.43,772.55],[772.59,772.67],[772.73,773.21],[773.25,773.47],[773.53,773.81]]},{"id":145,"p":66,"en":"Now, I want to show you one last thing.","zh":"最后，我想给大家看一样东西。","s":774.73,"e":776.42,"w":[[774.85,774.93],[774.93,774.95],[774.95,775.05],[775.07,775.11],[775.11,775.21],[775.25,775.31],[775.47,775.61],[775.69,775.95],[776.01,776.17]]},{"id":146,"p":66,"en":"I call this a Life Calendar.","zh":"我把它叫作“人生日历”。","s":777.01,"e":779.28,"w":[[777.13,777.15],[777.15,777.35],[777.39,777.61],[778.17,778.19],[778.27,778.51],[778.55,779.03]]},{"id":147,"p":66,"en":"That's one box for every week of a 90-year life.","zh":"一个人活到九十岁，每一周是一个格子。","s":779.87,"e":784.15,"w":[[779.99,780.11],[780.27,780.41],[780.48,780.74],[780.84,780.92],[781.02,781.24],[781.42,781.7],[782.44,782.5],[782.54,782.56],[782.72,783.1],[783.22,783.44],[783.58,783.9]]},{"id":148,"p":66,"en":"That's not that many boxes, especially since we've already used a bunch of those.","zh":"格子并没有那么多，更何况我们已经用掉了不少。","s":784.8,"e":789.59,"w":[[784.92,785.1],[785.16,785.32],[785.36,785.5],[785.56,785.72],[785.8,786.36],[786.62,787.12],[787.22,787.52],[788.08,788.22],[788.22,788.4],[788.5,788.68],[788.7,788.72],[788.76,788.96],[788.98,789.02],[789.04,789.34]]},{"id":149,"p":66,"en":"So I think we need to all take a long, hard look at that calendar.","zh":"所以我认为我们都需要认真、仔细地看看这本日历。","s":790.06,"e":795.23,"w":[[790.18,790.24],[790.38,790.4],[790.42,790.62],[790.88,790.98],[791.14,791.3],[791.36,791.42],[791.72,792.06],[792.26,792.46],[792.48,792.5],[792.58,793.0],[793.1,793.42],[793.5,793.72],[793.94,794.02],[794.1,794.3],[794.42,794.98]]},{"id":150,"p":66,"en":"We need to think about what we're really procrastinating on, because everyone is procrastinating on something in life.","zh":"我们需要想一想，自己到底在拖延什么，因为每个人都在拖延人生中的某件事。","s":796.53,"e":803.04,"w":[[796.65,796.69],[796.69,796.79],[796.81,796.87],[796.89,797.05],[797.09,797.39],[797.51,797.65],[797.71,797.91],[797.99,798.31],[798.37,799.07],[799.11,799.19],[799.23,799.47],[799.63,800.19],[800.41,800.49],[800.53,801.29],[801.41,801.51],[801.75,802.17],[802.35,802.41],[802.47,802.79]]},{"id":151,"p":66,"en":"We need to stay aware of the Instant Gratification Monkey.","zh":"我们需要时刻留意那只及时行乐猴。","s":804.27,"e":807.24,"w":[[804.39,804.45],[804.49,804.63],[804.67,804.71],[804.81,805.01],[805.03,805.37],[805.41,805.47],[805.49,805.55],[805.63,805.91],[805.93,806.63],[806.69,806.99]]},{"id":152,"p":66,"en":"That's a job for all of us.","zh":"这是我们每个人的任务。","s":808.95,"e":811.31,"w":[[809.07,809.31],[809.35,809.37],[809.43,809.75],[810.21,810.33],[810.51,810.65],[810.71,810.8],[810.84,811.06]]},{"id":153,"p":66,"en":"And because there's not that many boxes on there, it's a job that should probably start today.","zh":"而且因为格子没有那么多，这项任务大概应该从今天就开始。","s":812.22,"e":816.63,"w":[[812.34,812.44],[812.62,812.9],[812.9,813.04],[813.04,813.12],[813.14,813.24],[813.24,813.38],[813.42,813.72],[813.76,813.84],[813.86,814.0],[814.0,814.08],[814.1,814.12],[814.18,814.46],[814.48,814.58],[814.62,814.76],[814.78,815.18],[815.28,815.6],[815.94,816.38]]},{"id":154,"p":67,"en":"Well, maybe not today, but ...","zh":"嗯，也许不是今天，但是……","s":816.84,"e":819.81,"w":[[816.96,817.1],[818.02,818.18],[818.24,818.38],[818.74,819.2],[819.4,819.56]]},{"id":155,"p":69,"en":"You know.","zh":"你懂的。","s":821.46,"e":822.09,"w":[[821.58,821.66],[821.68,821.84]]},{"id":156,"p":69,"en":"Sometime soon.","zh":"总之尽快吧。","s":823.1,"e":824.11,"w":[[823.22,823.62],[823.66,823.86]]},{"id":157,"p":70,"en":"Thank you.","zh":"谢谢大家。","s":824.94,"e":825.65,"w":[[825.06,825.28],[825.32,825.4]]}]};